"use client";

import { useCallback, useEffect, useId, useMemo, useRef, type KeyboardEvent } from "react";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Separator } from "@/components/ui/separator";
import { cn } from "@/lib/utils";
import { useControllableState } from "./hooks/use-controllable-state";
import { useDirection, type Direction } from "./hooks/use-direction";
import { enforceUniqueKeys } from "./lib/enforce-unique-keys";
import { orderItems } from "./lib/order-items";
import { resolveActiveItem } from "./lib/resolve-active-item";
import { EmptyPlaceholder } from "./parts/empty-placeholder";
import { SwitcherList } from "./parts/switcher-list";
import { SwitcherTriggerContent, switcherTriggerClassName } from "./parts/switcher-trigger";
import {
  defaultAccountSwitcherLabels,
  type AccountSwitcherLabels,
  type AccountSwitcherProps,
  type CollapsedPopoverSide,
  type SwitcherItem,
} from "./types";

/**
 * Labels over defaults (C2). The deprecated `aria-label` sits between them: it names
 * the list and builds the legacy trigger name unless `labels` sets those. An
 * `undefined` value never erases a default.
 */
function resolveLabels(
  labels: AccountSwitcherLabels | undefined,
  ariaLabel: string | undefined,
): Required<AccountSwitcherLabels> {
  const resolved = { ...defaultAccountSwitcherLabels };
  if (ariaLabel !== undefined) {
    resolved.list = ariaLabel;
    resolved.trigger = (current) => (current === null ? ariaLabel : `${ariaLabel}, current: ${current}`);
  }
  if (labels?.trigger !== undefined) resolved.trigger = labels.trigger;
  if (labels?.list !== undefined) resolved.list = labels.list;
  if (labels?.empty !== undefined) resolved.empty = labels.empty;
  return resolved;
}

/** `start` / `end` → the physical side for the resolved direction. */
function physicalSide(side: CollapsedPopoverSide, dir: Direction): "top" | "right" | "bottom" | "left" {
  if (side === "start") return dir === "rtl" ? "right" : "left";
  if (side === "end") return dir === "rtl" ? "left" : "right";
  return side;
}

/**
 * Account Switcher — popover-with-switchable-items primitive.
 *
 * See [`docs/procomps/account-switcher-procomp/`](../../../../../docs/procomps/account-switcher-procomp/)
 * for description + plan + guide. Locks L1–L14 (L1 + L7 revised in v0.3.0 — see the
 * loop doc), all PQs at default per 2026-05-23 GATE 2 close.
 */
export function AccountSwitcher(props: AccountSwitcherProps) {
  const {
    items,
    activeKey,
    onSelect,
    fallbackActiveItem,
    footerSlot,
    isCollapsed = false,
    collapsedPopoverSide = "end",
    dir: dirProp,
    groups,
    itemSize = "default",
    renderItem,
    labels: labelsProp,
    "aria-label": ariaLabel,
    ariaCurrent = "true",
    open: openProp,
    defaultOpen,
    onOpenChange,
    className,
  } = props;

  const listboxId = useId();
  const triggerRef = useRef<HTMLButtonElement>(null);
  const dir = useDirection(triggerRef, dirProp);
  const labels = useMemo(() => resolveLabels(labelsProp, ariaLabel), [labelsProp, ariaLabel]);

  const [open, setOpen] = useControllableState<boolean>({
    value: openProp,
    defaultValue: defaultOpen ?? false,
    onChange: onOpenChange,
    componentName: "account-switcher",
    valuePropName: "open",
  });

  // L3 + Q2 — dev-warn + strip duplicates once per items reference change.
  const dedupedItems = useMemo(() => enforceUniqueKeys(items), [items]);
  const ordered = useMemo(() => orderItems(dedupedItems, groups), [dedupedItems, groups]);

  // Dev-warn grouping mistakes once per change of the message — an inline `groups` literal
  // re-runs the memo every render, but the effect only re-runs when the text differs.
  const problemText = ordered.problems.join(" ");
  useEffect(() => {
    if (process.env.NODE_ENV === "production" || !problemText) return;
    console.warn(`[account-switcher] ${problemText}`);
  }, [problemText]);

  const activeResolution = useMemo(
    () => resolveActiveItem(dedupedItems, activeKey, fallbackActiveItem),
    [dedupedItems, activeKey, fallbackActiveItem],
  );

  const activeItem = activeResolution.kind === "empty" ? null : activeResolution.item;

  // F-cross-13 guard at the shadcn-primitive boundary. The consumer's
  // `onOpenChange` is shielded — `useControllableState` always calls it with
  // the validated `boolean`. Plan §10.
  const handlePrimitiveOpenChange = useCallback(
    (next: unknown) => {
      if (typeof next !== "boolean") return;
      setOpen(next);
    },
    [setOpen],
  );

  // L6 — active-item clicks close the popover but do NOT fire onSelect.
  const handleItemClick = useCallback(
    (item: SwitcherItem) => {
      if (item.key === activeItem?.key) {
        setOpen(false);
        return;
      }
      onSelect(item);
      setOpen(false);
    },
    [activeItem?.key, onSelect, setOpen],
  );

  // AW1 — ↓ / ↑ on the closed trigger open the list (the popover primitive has no key handling).
  const handleTriggerKeyDown = useCallback(
    (event: KeyboardEvent<HTMLButtonElement>) => {
      if (open || (event.key !== "ArrowDown" && event.key !== "ArrowUp")) return;
      // Plain or Alt+arrow only (APG) — leave Ctrl / Meta / Shift combos to the app.
      if (event.ctrlKey || event.metaKey || event.shiftKey || event.nativeEvent.isComposing) return;
      event.preventDefault();
      setOpen(true);
    },
    [open, setOpen],
  );

  // Empty-state branch (Q1)
  if (activeResolution.kind === "empty") {
    return (
      <EmptyPlaceholder
        // Same direction context as the trigger: `useDirection` resolves once after mount, so a
        // switcher that mounts empty (items still loading) must still read its direction.
        ref={triggerRef}
        ariaLabel={labels.trigger(null)}
        emptyText={labels.empty}
        isCollapsed={isCollapsed}
        className={className}
      />
    );
  }

  const popoverSide = isCollapsed ? physicalSide(collapsedPopoverSide, dir) : "bottom";

  return (
    <Popover open={open} onOpenChange={handlePrimitiveOpenChange}>
      {/* v0.1.1 (F-cross-13 path-b): no `asChild` — Base UI's PopoverTrigger
          rejects it. The trigger IS the button: both backends render a native
          <button> and pass native DOM props straight through. v0.3.0: a listbox
          button (was role="combobox" — focus moves into the list, so the footer
          stays reachable with Tab). */}
      <PopoverTrigger
        ref={triggerRef}
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? listboxId : undefined}
        aria-label={labels.trigger(activeResolution.item.label)}
        onKeyDown={handleTriggerKeyDown}
        className={switcherTriggerClassName({ isCollapsed, className })}
      >
        <SwitcherTriggerContent activeItem={activeItem} isCollapsed={isCollapsed} />
      </PopoverTrigger>
      <PopoverContent
        side={popoverSide}
        align="start"
        sideOffset={4}
        // The content is portaled to <body>: carry the direction so an RTL section
        // of an LTR page still gets an RTL list.
        dir={dir}
        // Radix renders the content as role="dialog"; a dialog needs a name.
        aria-label={labels.list}
        // No collisionPadding — Radix-only prop; Base UI's PopoverContent
        // rejects it (F-cross-13). Both backends still collision-flip.
        className={cn(
          "gap-0 p-1",
          // Expanded: width = trigger width exactly, class only (no inline style — it would beat
          // the class and leave Base UI content-sized; no min-width — it made the list wider than
          // a narrow sidebar trigger). Radix exposes --radix-popover-trigger-width, Base UI
          // --anchor-width (F-cross-13). Collapsed: content-sized with a 14rem floor.
          isCollapsed ? "w-auto min-w-56" : "w-(--radix-popover-trigger-width,var(--anchor-width))",
        )}
      >
        <SwitcherList
          id={listboxId}
          label={labels.list}
          sections={ordered.sections}
          flat={ordered.flat}
          activeKey={activeResolution.item.key}
          ariaCurrent={ariaCurrent}
          itemSize={itemSize}
          renderItem={renderItem}
          onSelect={handleItemClick}
        />
        {footerSlot ? (
          <>
            <Separator className="my-1" />
            <div className="px-1 pb-1">{footerSlot}</div>
          </>
        ) : null}
      </PopoverContent>
    </Popover>
  );
}

export { AccountSwitcher } from "./account-switcher";
export { defaultAccountSwitcherLabels } from "./types";
export type {
  AccountSwitcherProps,
  AccountSwitcherAriaCurrent,
  AccountSwitcherLabels,
  CollapsedPopoverSide,
  SwitcherGroup,
  SwitcherItem,
  SwitcherItemRenderState,
} from "./types";

// @ilinxa/account-switcher 0.3.0

import type { ComponentType, ReactNode } from "react";

/**
 * Single item in the switcher list.
 *
 * Dual-entry items for the same conceptual account (e.g., business-mode +
 * cms-sub-mode of the same business) use distinct keys like `biz-acme` +
 * `cms-biz-acme`. Library enforces key uniqueness at render (L3 / Q2).
 */
export interface SwitcherItem {
  /** Stable unique key. Used for active resolution + React reconciliation. */
  key: string;
  /** Trigger + row label. Library does NOT i18n; consumer pre-translates. */
  label: string;
  /**
   * Optional icon. Library accepts both ReactNode (already-rendered JSX) and
   * ComponentType (lucide-react icons, custom icon components, etc.) so
   * consumers aren't forced into a single icon library (I-4). An avatar is a
   * ReactNode here — pair it with `itemSize="lg"`.
   */
  icon?: ReactNode | ComponentType<{ className?: string }>;
  /**
   * Optional href. The switcher fires `onSelect(item)` regardless of href —
   * consumer wires routing inside `onSelect` (router.push for SPA, anchor for
   * SSR fallbacks, or both). Library does not render `<a>` tags itself.
   */
  href?: string;
  /**
   * Id of the group this item renders under (see `AccountSwitcherProps.groups`).
   * Items without a group render first. An id missing from `groups` dev-warns and
   * renders the item ungrouped.
   */
  group?: string;
  /** Optional second line under the label (e.g. a role or a handle). Rows only — not the trigger. */
  description?: ReactNode;
}

/** A heading in the list. Order of `groups` = order of the groups on screen and for the keyboard. */
export interface SwitcherGroup {
  id: string;
  /** Heading text; it also names the group (`role="group"` + `aria-labelledby`). */
  label: ReactNode;
}

/**
 * Every user-facing string (consumer contract C2). Pass any subset — a missing or
 * `undefined` key keeps the default.
 */
export interface AccountSwitcherLabels {
  /**
   * The trigger's accessible name; `current` is the active item's label, or `null` when
   * nothing resolves (the disabled empty placeholder). Default:
   * `"Switch account context, current: <label>"` / `"Switch account context"`.
   */
  trigger?: (current: string | null) => string;
  /** The list's accessible name. Default: `"Switch account context"`. */
  list?: string;
  /** Text of the disabled placeholder shown when there are no items. Default: `"No items available"`. */
  empty?: string;
}

export const defaultAccountSwitcherLabels: Required<AccountSwitcherLabels> = {
  trigger: (current) =>
    current === null ? "Switch account context" : `Switch account context, current: ${current}`,
  list: "Switch account context",
  empty: "No items available",
};

/** State passed to `renderItem`. */
export interface SwitcherItemRenderState {
  /** The item is the active one (it carries `aria-selected="true"`). */
  active: boolean;
}

/**
 * Value applied to the active item's `aria-current` attribute. Default
 * `"true"` (generic active-state semantic, correct for a switcher per L14).
 * Consumers using the switcher as primary navigation pick `"page"`;
 * stepper-style usages pick `"step"`. Pass `false` to omit the attribute.
 */
export type AccountSwitcherAriaCurrent =
  | "true"
  | "page"
  | "step"
  | "location"
  | "date"
  | "time"
  | false;

/**
 * Side of the trigger the popover opens to when `isCollapsed` is true.
 * `"start"` / `"end"` follow the direction (`"end"` = right in LTR, left in RTL);
 * the physical values stay as they are. Default `"end"`.
 *
 * The popover still flips to the opposite side when it would not fit — the
 * primitive's collision handling always applies and is not configurable here.
 * For strict positioning, constrain the trigger's container instead.
 */
export type CollapsedPopoverSide = "start" | "end" | "right" | "left" | "top" | "bottom";

export interface AccountSwitcherProps {
  /** Ordered list. Consumer controls ordering (L2); `groups` then buckets it. */
  items: ReadonlyArray<SwitcherItem>;
  /**
   * Currently-active item's key. When null OR not found in items, falls
   * back to `fallbackActiveItem` (if provided) then to `items[0]`. Empty
   * items + no fallback → disabled placeholder button (L4, Q1).
   */
  activeKey: string | null;
  /** Fires on item click. Active-item clicks are no-ops at library level (L6). */
  onSelect: (item: SwitcherItem) => void;

  /** Shown in trigger when `activeKey` doesn't resolve (L4, I-1). */
  fallbackActiveItem?: SwitcherItem;
  /** Rendered below items, separated by divider when present (L5, Q7). Reachable with Tab from the list. */
  footerSlot?: ReactNode;
  /** When true, trigger collapses to icon-only mode (L10). */
  isCollapsed?: boolean;
  /** Side the popover opens to when `isCollapsed` is true. Default `"end"` (inline end). */
  collapsedPopoverSide?: CollapsedPopoverSide;
  /**
   * Text direction for the side and the popover content. Default: the trigger's
   * resolved direction (nearest `dir`, read after mount).
   */
  dir?: "ltr" | "rtl";
  /** Group headings + order. Items reference them through `item.group`. */
  groups?: ReadonlyArray<SwitcherGroup>;
  /** Row size. `"lg"` = 32 px icon / avatar box for a two-line row. Default `"default"`. */
  itemSize?: "default" | "lg";
  /**
   * Replaces a row's content (icon, label, description, check). The option element,
   * its roles, keyboard and selection stay the library's — don't render interactive
   * elements inside.
   */
  renderItem?: (item: SwitcherItem, state: SwitcherItemRenderState) => ReactNode;
  /** User-facing strings (C2). */
  labels?: AccountSwitcherLabels;
  /**
   * @deprecated Use `labels.list` and `labels.trigger`. Still honoured when those
   * aren't given: it names the list, and the trigger reads `"<aria-label>, current: <label>"`.
   */
  "aria-label"?: string;
  /** Value applied to active item's `aria-current`. Default `"true"` (L14). */
  ariaCurrent?: AccountSwitcherAriaCurrent;

  /**
   * Controlled-open state (L13). When provided, makes the popover controlled.
   * Pair with `onOpenChange` to receive state-change events. Switching between
   * controlled and uncontrolled (e.g., `open={undefined}` → `open={false}`)
   * fires a dev-mode warning — pick one mode at mount time.
   */
  open?: boolean;
  /** Initial open state for uncontrolled mode (L13). Default `false`. */
  defaultOpen?: boolean;
  /**
   * Fires when popover open state changes (L13). F-cross-13 typeof-guarded
   * internally — receives only `boolean`, never `unknown`.
   */
  onOpenChange?: (next: boolean) => void;

  /** Pass-through to trigger element (L1 surface contract). */
  className?: string;
}

import { useCallback, useEffect, useRef, useState } from "react";

interface UseControllableStateOpts<T> {
  /** Controlled value. When provided, state is fully controlled by parent. */
  value?: T;
  /** Initial value for uncontrolled mode. */
  defaultValue: T;
  /** Fires on every state change (both modes). */
  onChange?: (next: T) => void;
  /** Component name used in dev warnings. */
  componentName: string;
  /** Prop name used in dev warnings (e.g., `"open"`). */
  valuePropName: string;
}

/**
 * Controlled+uncontrolled state-machine helper.
 *
 * Plan §5.1 + re-validation Finding 1 (⚠️ HIGH):
 *   - Locks the controlled/uncontrolled mode based on the FIRST render's
 *     `value` and dev-warns when consumers flip modes mid-life. Switching
 *     between `value={undefined}` and `value={someBoolean}` is the classic
 *     React anti-pattern; we don't silently swap modes.
 *   - Dev-warns when controlled mode is used without an `onChange` handler
 *     (popover would appear frozen).
 *
 * Both warns are gated on `process.env.NODE_ENV !== "production"` so they
 * tree-shake out of prod bundles.
 *
 * Internal helper — not exported from the procomp's public API.
 */
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
  componentName,
  valuePropName,
}: UseControllableStateOpts<T>): readonly [T, (next: T) => void] {
  const [internal, setInternal] = useState<T>(defaultValue);
  const isControlled = value !== undefined;
  const onChangeRef = useRef(onChange);
  useEffect(() => {
    onChangeRef.current = onChange;
  });

  const wasControlledRef = useRef(isControlled);
  useEffect(() => {
    if (process.env.NODE_ENV === "production") return;
    if (wasControlledRef.current !== isControlled) {
      console.warn(
        `[${componentName}] \`${valuePropName}\` switched from ${
          wasControlledRef.current ? "controlled" : "uncontrolled"
        } to ${
          isControlled ? "controlled" : "uncontrolled"
        } mode. Components should not switch modes mid-life; pick one at mount.`,
      );
      wasControlledRef.current = isControlled;
    }
  }, [isControlled, componentName, valuePropName]);

  useEffect(() => {
    if (process.env.NODE_ENV === "production") return;
    if (isControlled && !onChangeRef.current) {
      const capitalized = valuePropName.charAt(0).toUpperCase() + valuePropName.slice(1);
      console.warn(
        `[${componentName}] \`${valuePropName}\` is controlled but no onChange handler was provided. ` +
          `State will appear frozen. Pass \`on${capitalized}Change\` ` +
          `(or use the uncontrolled variant by passing \`default${capitalized}\` instead).`,
      );
    }
  }, [isControlled, componentName, valuePropName]);

  const current = isControlled ? (value as T) : internal;

  const set = useCallback(
    (next: T) => {
      if (!isControlled) setInternal(next);
      onChangeRef.current?.(next);
    },
    [isControlled],
  );

  return [current, set] as const;
}

"use client";

import { useEffect, useLayoutEffect, useState } from "react";

const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export type Direction = "ltr" | "rtl";

/**
 * Resolves text direction (consumer contract C4 / R6): the `dir` prop wins; otherwise the
 * element's direction, read after mount — the computed `direction`, or the nearest explicit
 * non-`auto` `[dir]` ancestor (jsdom has no UA stylesheet for `dir`); otherwise `"ltr"`.
 *
 * The server render and the first client render both return the prop or `"ltr"`, so markup
 * must not depend on the resolved value before mount. Key handling, swipe, carousel and
 * transition logic may. A later direction change is not observed — pass `dir` if the app
 * switches direction at runtime without remounting.
 *
 * Directional props take `"start" | "end"`; physical values stay only as deprecated aliases.
 * Copy into a component's `hooks/`. Canonical copy: `_template/_snippets/` (tests next to it).
 */
export function useDirection(
  ref: React.RefObject<HTMLElement | null>,
  dirProp?: Direction,
): Direction {
  const [resolved, setResolved] = useState<Direction>("ltr");
  useIsoLayoutEffect(() => {
    if (dirProp) return;
    const el = ref.current;
    if (!el) return;
    const explicit = el.closest('[dir]:not([dir="auto"])')?.getAttribute("dir")?.toLowerCase();
    const rtl = getComputedStyle(el).direction === "rtl" || explicit === "rtl";
    setResolved(rtl ? "rtl" : "ltr");
  }, [dirProp, ref]);
  return dirProp ?? resolved;
}

import type { SwitcherItem } from "../types";

/**
 * Strip duplicate-key entries and dev-warn about the violation.
 *
 * Per L3 + Q2 — matches React's own key-uniqueness warning semantics:
 *   - Production: silent strip, last-write-wins-by-position (preserves first
 *     occurrence by source order)
 *   - Development: console.warn listing each duplicate key
 *
 * Callers should wrap in `useMemo([items])` so the dedup pass and the
 * (potential) warn fire once per items-reference change, not per render.
 */
export function enforceUniqueKeys(
  items: ReadonlyArray<SwitcherItem>,
): ReadonlyArray<SwitcherItem> {
  // Fast path (v0.1.0 review F-01): no duplicates → return the input, no new array.
  const keys = new Set<string>();
  for (const item of items) keys.add(item.key);
  if (keys.size === items.length) return items;

  const seen = new Set<string>();
  const deduped: SwitcherItem[] = [];
  const duplicateKeys: string[] = [];
  for (const item of items) {
    if (seen.has(item.key)) {
      duplicateKeys.push(item.key);
      continue;
    }
    seen.add(item.key);
    deduped.push(item);
  }
  if (duplicateKeys.length > 0 && process.env.NODE_ENV !== "production") {
    console.warn(
      `[account-switcher] Duplicate item keys stripped: ${duplicateKeys.join(", ")}. ` +
        `Each item must have a unique \`key\`. First occurrence preserved by source order.`,
    );
  }
  return deduped;
}

import type { ReactNode } from "react";
import type { SwitcherGroup, SwitcherItem } from "../types";

/** One block of the list: the ungrouped items (`id: null`) or one group with its heading. */
export interface SwitcherSection {
  id: string | null;
  label: ReactNode;
  items: SwitcherItem[];
}

/**
 * Bucket items for rendering. Ungrouped items come first (array order), then each
 * group in `groups` order with its items in array order; empty groups are skipped.
 * A repeated group id keeps its first occurrence. An item whose `group` is not in
 * `groups` renders ungrouped.
 *
 * `flat` is the rendered order — the keyboard walks it, so arrow keys always follow
 * what the user sees. `problems` lists both input mistakes; the component dev-warns
 * them once per change (pure here, so inline `groups` literals don't warn every render).
 */
export function orderItems(
  items: ReadonlyArray<SwitcherItem>,
  groups: ReadonlyArray<SwitcherGroup> | undefined,
): { sections: SwitcherSection[]; flat: SwitcherItem[]; problems: string[] } {
  const known = new Map<string, SwitcherItem[]>();
  const uniqueGroups: SwitcherGroup[] = [];
  const duplicateGroups: string[] = [];
  for (const g of groups ?? []) {
    if (known.has(g.id)) {
      duplicateGroups.push(g.id);
      continue;
    }
    known.set(g.id, []);
    uniqueGroups.push(g);
  }
  const ungrouped: SwitcherItem[] = [];
  const unknown: string[] = [];
  for (const item of items) {
    const bucket = item.group === undefined ? undefined : known.get(item.group);
    if (bucket) {
      bucket.push(item);
      continue;
    }
    if (item.group !== undefined) unknown.push(`${item.key} → ${item.group}`);
    ungrouped.push(item);
  }

  const problems: string[] = [];
  if (duplicateGroups.length > 0) {
    problems.push(`Duplicate group ids in \`groups\`; first occurrence kept: ${duplicateGroups.join(", ")}.`);
  }
  if (unknown.length > 0) {
    problems.push(`Items reference a group missing from \`groups\`; rendered ungrouped: ${unknown.join(", ")}.`);
  }

  const sections: SwitcherSection[] = [];
  if (ungrouped.length > 0) sections.push({ id: null, label: null, items: ungrouped });
  for (const g of uniqueGroups) {
    const bucket = known.get(g.id);
    if (bucket && bucket.length > 0) sections.push({ id: g.id, label: g.label, items: bucket });
  }
  return { sections, flat: sections.flatMap((s) => s.items), problems };
}

import type { SwitcherItem } from "../types";

/**
 * Result of the active-item resolution pipeline (plan §6).
 *
 * Discriminated union so the renderer can react differently per branch —
 * e.g., visually mark `kind: "fallback"` if the design later wants to, or
 * disable the trigger in the `kind: "empty"` case (Q1 default).
 */
export type ResolvedActive =
  | { kind: "resolved"; item: SwitcherItem }
  | { kind: "fallback"; item: SwitcherItem }
  | { kind: "first"; item: SwitcherItem }
  | { kind: "empty" };

/**
 * Resolve the item to show in the trigger.
 *
 * Priority (L4 + Q1):
 *   1. items.find((i) => i.key === activeKey)   → kind: "resolved"
 *   2. fallbackActiveItem                       → kind: "fallback"
 *   3. items[0]                                 → kind: "first"
 *   4. (none)                                   → kind: "empty"
 */
export function resolveActiveItem(
  items: ReadonlyArray<SwitcherItem>,
  activeKey: string | null,
  fallback: SwitcherItem | undefined,
): ResolvedActive {
  if (activeKey !== null) {
    const match = items.find((i) => i.key === activeKey);
    if (match) return { kind: "resolved", item: match };
  }
  if (fallback) return { kind: "fallback", item: fallback };
  if (items.length > 0) return { kind: "first", item: items[0]! };
  return { kind: "empty" };
}

import type { Ref } from "react";
import { cn } from "@/lib/utils";

interface EmptyPlaceholderProps {
  ariaLabel: string;
  /** Visible text (`labels.empty`). */
  emptyText: string;
  isCollapsed: boolean;
  className?: string;
  ref?: Ref<HTMLButtonElement>;
}

/**
 * Disabled trigger rendered when `items` is empty AND no `fallbackActiveItem`
 * is provided (Q1 default: disabled with placeholder text). Defensive
 * against the source's empty-array crash (I-2).
 */
export function EmptyPlaceholder({ ariaLabel, emptyText, isCollapsed, className, ref }: EmptyPlaceholderProps) {
  if (isCollapsed) {
    return (
      <button
        ref={ref}
        type="button"
        disabled
        aria-label={ariaLabel}
        className={cn(
          "inline-flex h-10 w-10 cursor-not-allowed items-center justify-center rounded-md border border-dashed border-border bg-card text-muted-foreground opacity-60",
          className,
        )}
      >
        <span className="text-xs">—</span>
      </button>
    );
  }
  return (
    <button
      ref={ref}
      type="button"
      disabled
      aria-label={ariaLabel}
      className={cn(
        "inline-flex w-full cursor-not-allowed items-center justify-between rounded-md border border-dashed border-border bg-card px-3 py-2 text-sm text-muted-foreground opacity-60",
        className,
      )}
    >
      <span>{emptyText}</span>
    </button>
  );
}

import { createElement, isValidElement, type ComponentType, type ReactNode } from "react";

type IconLike = ReactNode | ComponentType<{ className?: string }>;

/**
 * Render an icon prop that accepts either an already-rendered ReactNode
 * (JSX) OR a ComponentType (lucide-react icon, custom component, forwardRef
 * object). Handles all three shapes:
 *
 *   1. JSX element  → return as-is
 *   2. function     → call with { className }
 *   3. forwardRef / memo / exotic component (object with $$typeof) →
 *      use createElement so lucide-react v0.475+ forwardRef icons work
 *      (mirrors the app-sidebar Icon helper fix from 52e5f33).
 *   4. primitive (string/number) → wrap as-is
 *   5. null / undefined → null
 */
export function renderIcon(icon: IconLike | undefined, className?: string): ReactNode {
  if (icon === null || icon === undefined) return null;

  // Already a rendered element
  if (isValidElement(icon)) return icon;

  // Function component
  if (typeof icon === "function") {
    return createElement(icon as ComponentType<{ className?: string }>, { className });
  }

  // forwardRef / memo / exotic (object with $$typeof) — lucide-react v0.475+
  if (typeof icon === "object" && icon !== null && "$$typeof" in icon) {
    return createElement(icon as unknown as ComponentType<{ className?: string }>, { className });
  }

  // Primitive (string / number) — render directly
  return icon as ReactNode;
}

import type { AriaAttributes, ReactNode, Ref } from "react";
import { Check } from "lucide-react";
import { cn } from "@/lib/utils";
import type { AccountSwitcherAriaCurrent, AccountSwitcherProps, SwitcherItem } from "../types";
import { renderIcon } from "./render-icon";

interface SwitcherItemRowProps {
  item: SwitcherItem;
  isActive: boolean;
  ariaCurrent: AccountSwitcherAriaCurrent;
  onSelect: () => void;
  /** Roving tab stop: only the list's current option is tabbable (APG listbox). */
  tabbable?: boolean;
  onFocus?: () => void;
  itemSize?: AccountSwitcherProps["itemSize"];
  renderItem?: AccountSwitcherProps["renderItem"];
  ref?: Ref<HTMLButtonElement>;
}

/**
 * Single option inside the popover listbox. Renders icon (if present) + label
 * (+ description) + Check trail (when active), or the host's `renderItem`
 * content. Active rows are no-op on select (L6) — the handler in the main
 * component routes around them. A native `<button>` keeps Enter / Space
 * activation; arrow keys are the list's job (`switcher-list.tsx`).
 *
 * `aria-current` resolution per L14 + PQ3 (data-active for CSS hooks
 * regardless of aria value).
 */
export function SwitcherItemRow({
  item,
  isActive,
  ariaCurrent,
  onSelect,
  tabbable = true,
  onFocus,
  itemSize = "default",
  renderItem,
  ref,
}: SwitcherItemRowProps) {
  const lg = itemSize === "lg";
  return (
    <button
      ref={ref}
      type="button"
      role="option"
      aria-selected={isActive}
      aria-current={resolveAriaCurrent(isActive, ariaCurrent)}
      data-active={isActive || undefined}
      data-key={item.key}
      tabIndex={tabbable ? 0 : -1}
      onClick={onSelect}
      onFocus={onFocus}
      className={cn(
        "group flex w-full items-center gap-2.5 rounded-md px-2 py-1.5 text-start text-sm transition-colors",
        lg && "gap-3 py-2",
        "hover:bg-accent hover:text-accent-foreground",
        // Keyboard focus gets an inset ring as well — hover and the active row share the accent
        // background, so the background alone can't say which row has focus.
        "focus-visible:bg-accent focus-visible:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset",
        isActive && "bg-accent/60 text-accent-foreground",
      )}
    >
      {renderItem ? (
        renderItem(item, { active: isActive })
      ) : (
        <>
          {item.icon ? (
            <span
              className={cn(
                "flex shrink-0 items-center justify-center text-muted-foreground group-hover:text-foreground",
                lg
                  ? "size-8 overflow-hidden rounded-full [&>img]:size-full [&>img]:object-cover"
                  : "h-4 w-4",
              )}
            >
              {renderIcon(item.icon, lg ? "size-5" : "h-4 w-4") as ReactNode}
            </span>
          ) : null}
          {item.description ? (
            <span className="flex min-w-0 flex-1 flex-col">
              <span className="truncate">{item.label}</span>
              <span className="truncate text-xs text-muted-foreground">{item.description}</span>
            </span>
          ) : (
            <span className="min-w-0 flex-1 truncate">{item.label}</span>
          )}
          {isActive ? (
            <Check className="ms-auto h-4 w-4 shrink-0 text-foreground" aria-hidden="true" />
          ) : null}
        </>
      )}
    </button>
  );
}

function resolveAriaCurrent(
  isActive: boolean,
  override: AccountSwitcherAriaCurrent,
): AriaAttributes["aria-current"] | undefined {
  if (!isActive) return undefined;
  if (override === false) return undefined;
  return override;
}

"use client";

import { useEffect, useId, useRef, useState, type KeyboardEvent } from "react";
import type { SwitcherSection } from "../lib/order-items";
import type { AccountSwitcherProps, SwitcherItem } from "../types";
import { SwitcherItemRow } from "./switcher-item-row";

interface SwitcherListProps {
  id: string;
  label: string;
  sections: SwitcherSection[];
  /** Rendered order — what the arrow keys walk. */
  flat: SwitcherItem[];
  activeKey: string | null;
  ariaCurrent: NonNullable<AccountSwitcherProps["ariaCurrent"]>;
  itemSize: AccountSwitcherProps["itemSize"];
  renderItem: AccountSwitcherProps["renderItem"];
  onSelect: (item: SwitcherItem) => void;
}

const NAV_KEYS = new Set(["ArrowDown", "ArrowUp", "Home", "End"]);

/**
 * The listbox (APG listbox, roving focus): one Tab stop for the whole list — only
 * the current option is tabbable — ↓ / ↑ move (no wrap), Home / End jump, Enter /
 * Space select (native button). Escape is the popover's (closes, focus back on the
 * trigger). Groups render as `role="group"` labelled by their heading.
 *
 * Mounted only while the popover is open, so every open starts on the active item
 * (else the first).
 */
export function SwitcherList({
  id,
  label,
  sections,
  flat,
  activeKey,
  ariaCurrent,
  itemSize,
  renderItem,
  onSelect,
}: SwitcherListProps) {
  const headingIdBase = useId();
  const listRef = useRef<HTMLDivElement>(null);
  const optionRefs = useRef(new Map<string, HTMLButtonElement>());
  const [focusKey, setFocusKey] = useState<string | null>(null);

  // The tab stop: the last focused option while it still exists, else the active item, else the first.
  const has = (key: string | null) => key !== null && flat.some((i) => i.key === key);
  const currentKey = has(focusKey) ? focusKey : has(activeKey) ? activeKey : (flat[0]?.key ?? null);

  // Land focus on the tab stop when the list opens. Radix's auto-focus already picks it (the
  // only tabbable option); Base UI may focus the popup itself, so re-check after its own
  // initial-focus pass. Focus moves only from nowhere (<body>) or from the popup root — never
  // away from something the user (or an autofocusing footer) already focused.
  useEffect(() => {
    const focusStop = () => {
      const list = listRef.current;
      const stop = list?.querySelector<HTMLElement>('[role="option"][tabindex="0"]');
      if (!list || !stop) return;
      const active = document.activeElement;
      const popup = list.closest('[data-slot="popover-content"]') ?? list.parentElement;
      if (active && active !== document.body && active !== popup) return;
      stop.focus();
    };
    focusStop();
    const frame = requestAnimationFrame(focusStop);
    return () => cancelAnimationFrame(frame);
  }, []);

  // A live update removed the focused option: the browser drops focus to <body> and the arrow
  // keys stop working. Put focus back on the new tab stop.
  const focusedRemoved = focusKey !== null && !has(focusKey);
  useEffect(() => {
    if (!focusedRemoved || currentKey === null) return;
    const active = document.activeElement;
    if (active && active !== document.body) return;
    optionRefs.current.get(currentKey)?.focus();
  }, [focusedRemoved, currentKey]);

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (!NAV_KEYS.has(event.key)) return;
    const target = event.target as HTMLElement;
    if (target.getAttribute("role") !== "option") return;
    const index = flat.findIndex((i) => i.key === target.dataset.key);
    if (index === -1) return;
    const nextIndex =
      event.key === "Home"
        ? 0
        : event.key === "End"
          ? flat.length - 1
          : event.key === "ArrowDown"
            ? Math.min(index + 1, flat.length - 1)
            : Math.max(index - 1, 0);
    event.preventDefault();
    const next = flat[nextIndex];
    if (!next) return;
    setFocusKey(next.key);
    optionRefs.current.get(next.key)?.focus();
  };

  const renderRow = (item: SwitcherItem) => (
    <SwitcherItemRow
      key={item.key}
      ref={(el) => {
        if (el) optionRefs.current.set(item.key, el);
        else optionRefs.current.delete(item.key);
      }}
      item={item}
      isActive={item.key === activeKey}
      ariaCurrent={ariaCurrent}
      tabbable={item.key === currentKey}
      onFocus={() => setFocusKey(item.key)}
      itemSize={itemSize}
      renderItem={renderItem}
      onSelect={() => onSelect(item)}
    />
  );

  return (
    <div
      ref={listRef}
      id={id}
      role="listbox"
      aria-label={label}
      onKeyDown={handleKeyDown}
      className="flex flex-col gap-0.5"
    >
      {sections.map((section, index) => {
        if (section.id === null) return section.items.map(renderRow);
        // Position, not the group id: an id with a space would split `aria-labelledby`.
        const headingId = `${headingIdBase}-g${index}`;
        return (
          <div key={section.id} role="group" aria-labelledby={headingId} className="flex flex-col gap-0.5">
            <div
              id={headingId}
              role="presentation"
              className="px-2 pt-2 pb-1 text-xs font-medium text-muted-foreground"
            >
              {section.label}
            </div>
            {section.items.map(renderRow)}
          </div>
        );
      })}
    </div>
  );
}

import { forwardRef, type ReactNode } from "react";
import { ChevronsUpDown } from "lucide-react";
import { cn } from "@/lib/utils";
import type { SwitcherItem } from "../types";
import { renderIcon } from "./render-icon";

interface SwitcherTriggerProps {
  /** Resolved active item (may be a fallback / first / etc.). */
  activeItem: SwitcherItem | null;
  /** Trigger ARIA label. Composed with active label per PQ4. */
  ariaLabel: string;
  /** ID of the listbox the trigger controls; set only while it is open (it isn't in the DOM before). */
  ariaControls?: string;
  /** When true, render icon-only 40x40 square; no label, no chevron (L10). */
  isCollapsed: boolean;
  /** Whether the popover is currently open (drives aria-expanded). */
  open: boolean;
  /** Whether the trigger is disabled (e.g., empty-items state). */
  disabled?: boolean;
  /** Pass-through className from props. */
  className?: string;
  /** Click handler (Popover.Trigger native). */
  onClick?: () => void;
}

/**
 * PQ4 — the legacy composed name ("Switch account context, current: Acme Corp").
 * Since v0.3.0 the assembly names the trigger with `labels.trigger(current)`; this
 * stays for the deprecated `aria-label` prop and for direct importers.
 */
export function composeSwitcherTriggerAriaLabel(
  ariaLabel: string,
  activeItem: SwitcherItem | null,
): string {
  return activeItem ? `${ariaLabel}, current: ${activeItem.label}` : ariaLabel;
}

/**
 * First user-perceived character of a label for the collapsed trigger — a whole
 * emoji or accented letter, never half a surrogate pair.
 */
export function firstGrapheme(label: string | undefined): string | undefined {
  if (!label) return undefined;
  if (typeof Intl !== "undefined" && "Segmenter" in Intl) {
    // Grapheme boundaries are locale-independent (UAX #29 default rules) → the root locale, explicitly.
    const first = new Intl.Segmenter("und", { granularity: "grapheme" }).segment(label)[Symbol.iterator]().next();
    if (!first.done) return first.value.segment;
  }
  return Array.from(label)[0];
}

/**
 * Trigger button classes — two branches per `isCollapsed`:
 *   - expanded: full-width with icon + label + chevron, width drives popover
 *     width via --radix-popover-trigger-width
 *   - collapsed: 40x40 icon-only square; popover opens to the side
 *
 * v0.1.1 (F-cross-13 path-b): exported as a class builder because the
 * assembly no longer mounts a <button> via `<PopoverTrigger asChild>` —
 * Base UI's PopoverTrigger has no `asChild` (and the CLI's render-rewrite
 * breaks mixed consumers). The primitive trigger IS the button now:
 * account-switcher.tsx renders
 * `<PopoverTrigger className={switcherTriggerClassName(…)}>` with
 * `<SwitcherTriggerContent>` inside, passing only native DOM props across
 * the shadcn-primitive boundary.
 */
export function switcherTriggerClassName({
  isCollapsed,
  className,
}: {
  isCollapsed: boolean;
  className?: string;
}): string {
  if (isCollapsed) {
    return cn(
      "inline-flex h-10 w-10 items-center justify-center rounded-md border border-border bg-card text-foreground transition-colors",
      "hover:bg-accent hover:text-accent-foreground",
      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
      "disabled:cursor-not-allowed disabled:opacity-50",
      className,
    );
  }
  return cn(
    "inline-flex w-full items-center gap-2 rounded-md border border-border bg-card px-3 py-2 text-sm text-foreground transition-colors",
    "hover:bg-accent hover:text-accent-foreground",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
    "disabled:cursor-not-allowed disabled:opacity-50",
    className,
  );
}

/**
 * Inner trigger content (icon / initial / label / chevron), backend-neutral —
 * rendered inside whichever button element hosts the trigger.
 */
export function SwitcherTriggerContent({
  activeItem,
  isCollapsed,
}: {
  activeItem: SwitcherItem | null;
  isCollapsed: boolean;
}) {
  if (isCollapsed) {
    return activeItem?.icon ? (
      <>{renderIcon(activeItem.icon, "h-4 w-4") as ReactNode}</>
    ) : (
      <span className="text-xs font-medium uppercase">
        {firstGrapheme(activeItem?.label) ?? "?"}
      </span>
    );
  }
  return (
    <>
      {activeItem?.icon ? (
        <span className="flex h-4 w-4 shrink-0 items-center justify-center text-muted-foreground">
          {renderIcon(activeItem.icon, "h-4 w-4") as ReactNode}
        </span>
      ) : null}
      <span className="min-w-0 flex-1 truncate text-start">
        {activeItem?.label ?? "—"}
      </span>
      <ChevronsUpDown
        className="ms-auto h-4 w-4 shrink-0 text-muted-foreground"
        aria-hidden="true"
      />
    </>
  );
}

/**
 * Standalone trigger button — kept for API stability (the part file ships;
 * direct importers keep working). Since v0.3.0 it is a plain button with
 * `aria-haspopup="listbox"` (was `role="combobox"`), matching the assembly.
 * Since v0.1.1 the assembly no longer routes it through
 * `<PopoverTrigger asChild>` (F-cross-13) — see switcherTriggerClassName
 * above for the primitive-trigger path.
 */
export const SwitcherTrigger = forwardRef<HTMLButtonElement, SwitcherTriggerProps>(
  function SwitcherTrigger(
    { activeItem, ariaLabel, ariaControls, isCollapsed, open, disabled, className, onClick, ...rest },
    ref,
  ) {
    return (
      <button
        ref={ref}
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? ariaControls : undefined}
        aria-label={composeSwitcherTriggerAriaLabel(ariaLabel, activeItem)}
        disabled={disabled}
        onClick={onClick}
        className={switcherTriggerClassName({ isCollapsed, className })}
        {...rest}
      >
        <SwitcherTriggerContent activeItem={activeItem} isCollapsed={isCollapsed} />
      </button>
    );
  },
);
